2	 * DOM 表格解析：按表头语义匹配列，抽取广告系列行
3	 * 避免依赖哈希 class，适配 TikTok Seller / Ads 改版
4	 */
5	
6	import { HEADER_ALIASES } from '../lib/constants.js';
7	import { cleanText, parseNumber } from './normalize.js';
8	
9	/**
10	 * 判断表头文本属于哪个业务字段
11	 * @param {string} headerText
12	 * @returns {keyof typeof HEADER_ALIASES|null}
13	 */
14	export function matchHeaderField(headerText) {
15	  const t = cleanText(headerText).toLowerCase();
16	  if (!t) return null;
17	
18	  // 优先更具体的匹配（roi 先于 revenue 中的 "return"）
19	  const order = ['roi', 'spend', 'orders', 'revenue', 'campaign'];
20	  for (const field of order) {
21	    const aliases = HEADER_ALIASES[field];
22	    for (const a of aliases) {
23	      const al = a.toLowerCase();
24	      if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) continue;
25	      if (field === 'spend') {
26	        if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b/.test(t)) continue;
27	        if (
28	          t.includes('budget') &&
29	          !t.includes('spent') &&
30	          !t.includes('spend') &&
31	          !t.includes('cost') &&
32	          !t.includes('成本')
33	        ) {
34	          continue;
35	        }
36	      }
37	      if (field === 'campaign' && (al === '名称' || al === 'name')) {
38	        if (!/系列|campaign|广告|活动|product|品名/.test(t) && t !== '名称' && t !== 'name') {
39	          continue;
40	        }
41	      }
42	      return field;
43	    }
44	  }
45	  return null;
46	}
47	
48	/**
49	 * 从 thead / 首行收集表头
50	 * @param {HTMLTableElement} table
51	 * @returns {{cells: Element[], fields: (string|null)[]}}
52	 */
53	export function extractTableHeaders(table) {
54	  let headerRow = table.querySelector('thead tr');
55	  if (!headerRow) {
56	    headerRow = table.querySelector('tr');
57	  }
58	  if (!headerRow) return { cells: [], fields: [] };
59	
60	  const cells = [...headerRow.querySelectorAll('th, td')];
61	  const fields = cells.map((c) => matchHeaderField(c.innerText || c.textContent || ''));
62	  return { cells, fields };
63	}
64	
65	/**
66	 * 解析原生 HTML table
67	 * @param {HTMLTableElement} table
68	 * @returns {object[]}
69	 */
70	export function parseHtmlTable(table) {
71	  const { fields } = extractTableHeaders(table);
72	  if (!fields.some(Boolean)) return [];
73	
74	  const bodyRows = table.querySelectorAll('tbody tr');
75	  const rows = bodyRows.length
76	    ? [...bodyRows]
77	    : [...table.querySelectorAll('tr')].slice(1);
78	
79	  const results = [];
80	  for (const tr of rows) {
81	    const cells = [...tr.querySelectorAll('td, th')];
82	    if (!cells.length) continue;
83	    const row = {};
84	    fields.forEach((field, i) => {
85	      if (!field || !cells[i]) return;
86	      const text = cleanText(cells[i].innerText || cells[i].textContent || '');
87	      row[field] = field === 'campaign' ? text : text;
88	    });
89	    if (Object.keys(row).length) results.push(row);
90	  }
91	  return results;
92	}
93	
94	/**
95	 * 解析 div / role=table 的网格（常见于 Ant Design / 自定义表格）
96	 * @param {Element} root
97	 * @returns {object[]}
98	 */
99	export function parseRoleTable(root) {
100	  const headerCells = [
101	    ...root.querySelectorAll(
102	      '[role="columnheader"], .ant-table-thead th, [class*="table-header"] th, [class*="TableHeader"]'
103	    )
104	  ];
105	  if (!headerCells.length) return [];
106	
107	  const fields = headerCells.map((c) =>
108	    matchHeaderField(c.innerText || c.textContent || '')
109	  );
110	  if (!fields.some(Boolean)) return [];
111	
112	  const dataRows = [
113	    ...root.querySelectorAll(
114	      '[role="row"]:not(:has([role="columnheader"])), .ant-table-tbody tr, tbody tr'
115	    )
116	  ].filter((r) => r.querySelectorAll('[role="cell"], td').length);
117	
118	  const results = [];
119	  for (const tr of dataRows) {
120	    const cells = [...tr.querySelectorAll('[role="cell"], td')];
121	    if (!cells.length) continue;
122	    const row = {};
123	    fields.forEach((field, i) => {
124	      if (!field || !cells[i]) return;
125	      row[field] = cleanText(cells[i].innerText || cells[i].textContent || '');
126	    });
127	    if (Object.keys(row).length) results.push(row);
128	  }
129	  return results;
130	}
131	
132	/**
133	 * 启发式：页面上所有表格，取「匹配字段最多且行数最多」的一份
134	 * @param {Document} doc
135	 * @returns {{rows: object[], source: string}}
136	 */
137	export function scrapeTablesFromDocument(doc = document) {
138	  const candidates = [];
139	
140	  const tables = [...doc.querySelectorAll('table')];
141	  for (const table of tables) {
142	    const rows = parseHtmlTable(table);
143	    const score = scoreRows(rows);
144	    if (score > 0) {
145	      candidates.push({ rows, score, source: 'html-table' });
146	    }
147	  }
148	
149	  // 常见容器
150	  const containers = [
151	    ...doc.querySelectorAll(
152	      '.ant-table, [class*="Table"], [class*="data-table"], [role="table"], [class*="campaign"]'
153	    )
154	  ];
155	  for (const el of containers) {
156	    const rows = parseRoleTable(el);
157	    const score = scoreRows(rows);
158	    if (score > 0) {
159	      candidates.push({ rows, score, source: 'role-table' });
160	    }
161	  }
162	
163	  // 无 table 时：扫描「看起来像表头」的横向列表
164	  if (!candidates.length) {
165	    const heuristic = heuristicGridScan(doc);
166	    if (heuristic.rows.length) candidates.push({ ...heuristic, source: 'heuristic' });
167	  }
168	
169	  candidates.sort((a, b) => b.score - a.score);
170	  if (!candidates.length) {
171	    return { rows: [], source: 'none' };
172	  }
173	  return { rows: candidates[0].rows, source: candidates[0].source };
174	}
175	
176	function scoreRows(rows) {
177	  if (!rows?.length) return 0;
178	  let score = rows.length;
179	  const sample = rows.slice(0, 5);
180	  for (const r of sample) {
181	    if (r.campaign) score += 2;
182	    if (r.spend != null && r.spend !== '') score += 2;
183	    if (r.roi != null && r.roi !== '') score += 2;
184	    if (r.revenue != null && r.revenue !== '') score += 2;
185	    if (r.orders != null && r.orders !== '') score += 1;
186	  }
187	  return score;
188	}
189	
190	/**
191	 * 弱启发：找含多个表头关键词的行，下一行起当数据
192	 * @param {Document} doc
193	 */
194	function heuristicGridScan(doc) {
195	  const all = [...doc.querySelectorAll('div, tr, li')].slice(0, 2000);
196	  for (const el of all) {
197	    const children = [...el.children];
198	    if (children.length < 3 || children.length > 20) continue;
199	    const texts = children.map((c) => cleanText(c.innerText || '').slice(0, 40));
200	    const fields = texts.map(matchHeaderField);
201	    const hit = fields.filter(Boolean).length;
202	    if (hit < 3) continue;
203	
204	    // 同级后续兄弟中找相似结构
205	    const parent = el.parentElement;
206	    if (!parent) continue;
207	    const siblings = [...parent.children];
208	    const start = siblings.indexOf(el);
209	    const rows = [];
210	    for (let i = start + 1; i < Math.min(siblings.length, start + 200); i++) {
211	      const cells = [...siblings[i].children];
212	      if (cells.length < 2) continue;
213	      const row = {};
214	      fields.forEach((field, idx) => {
215	        if (!field || !cells[idx]) return;
216	        row[field] = cleanText(cells[idx].innerText || '');
217	      });
218	      if (row.campaign || row.spend || row.revenue) rows.push(row);
219	    }
220	    if (rows.length >= 1) {
221	      return { rows, score: scoreRows(rows) };
222	    }
223	  }
224	  return { rows: [], score: 0 };
225	}
226	
227	/**
228	 * 尝试从页面探测店铺名
229	 * @param {Document} doc
230	 */
231	export function detectStoreName(doc = document) {
232	  const title = cleanText(doc.title || '');
233	  // 常见：Shop name - TikTok ...
234	  const parts = title.split(/[-|–—]/).map(cleanText).filter(Boolean);
235	  if (parts.length >= 2) {
236	    // 去掉纯品牌词
237	    const skip = /tiktok|seller|ads|shop ads|campaign|dashboard/i;
238	    for (const p of parts) {
239	      if (!skip.test(p) && p.length > 1 && p.length < 80) return p;
240	    }
241	  }
242	
243	  // meta / 侧栏
244	  const candidates = [
245	    ...doc.querySelectorAll(
246	      '[class*="shop-name"], [class*="store-name"], [class*="seller-name"], [data-e2e*="shop"]'
247	    )
248	  ];
249	  for (const el of candidates) {
250	    const t = cleanText(el.innerText || '');
251	    if (t && t.length < 80) return t;
252	  }
253	  return '';
254	}
255	
256	// re-export for content script convenience
257	export { parseNumber };
