1	/**
2	 * 飞书多维表格写入
3	 * - 写入前拉取表字段，按别名映射真实列名
4	 * - 只写表里存在的字段，避免 FieldNameNotFound
5	 */
6	
7	import {
8	  BITABLE_FIELD_ALIASES,
9	  BITABLE_FIELDS,
10	  BITABLE_REQUIRED_KEYS,
11	  FEISHU
12	} from '../lib/constants.js';
13	import { getConfig } from '../lib/storage.js';
14	import { getTenantAccessToken } from './auth.js';
15	
16	/** @type {{ key: string, appToken: string, tableId: string, map: Record<string, {name:string,type:number}>, names: string[], at: number } | null} */
17	let fieldCache = null;
18	const FIELD_CACHE_TTL = 5 * 60 * 1000;
19	
20	/**
21	 * 业务记录 → 飞书 fields（使用固定首选名；实际写入走 resolve）
22	 * @param {object} row
23	 * @param {Record<string, {name:string,type:number}>} [resolvedMap]
24	 */
25	export function toBitableFields(row, resolvedMap) {
26	  const dateMs = row.date ? new Date(`${row.date}T00:00:00`).getTime() : Date.now();
27	  const scrapedMs = row.scrapedAt ? new Date(row.scrapedAt).getTime() : Date.now();
28	
29	  const logical = {
30	    date: dateMs,
31	    store: row.store || '',
32	    storeId: row.storeId || '',
33	    campaign: row.campaign || '',
34	    spend: Number(row.spend) || 0,
35	    orders: Number(row.orders) || 0,
36	    roi: Number(row.roi) || 0,
37	    revenue: Number(row.revenue) || 0,
38	    scrapedAt: scrapedMs,
39	    sourceUrl: row.sourceUrl || '',
40	    status: row.status || 'success'
41	  };
42	
43	  // 无映射时用默认中文名（兼容旧逻辑）
44	  if (!resolvedMap) {
45	    const out = {};
46	    for (const [k, v] of Object.entries(logical)) {
47	      const name = BITABLE_FIELDS[k];
48	      if (name) out[name] = v;
49	    }
50	    return out;
51	  }
52	
53	  const out = {};
54	  for (const [k, v] of Object.entries(logical)) {
55	    const meta = resolvedMap[k];
56	    if (!meta?.name) continue;
57	    out[meta.name] = coerceValue(v, meta.type);
58	  }
59	  return out;
60	}
61	
62	/**
63	 * @param {unknown} value
64	 * @param {number} type 飞书字段 type
65	 */
66	function coerceValue(value, type) {
67	  // 1 text, 3 single select, 4 multi, 15 url → string
68	  // 2 number → number
69	  // 5 datetime → ms
70	  if (type === 2) {
71	    const n = Number(value);
72	    return Number.isFinite(n) ? n : 0;
73	  }
74	  if (type === 5) {
75	    if (typeof value === 'number') return value;
76	    const t = new Date(value).getTime();
77	    return Number.isFinite(t) ? t : Date.now();
78	  }
79	  if (type === 3) {
80	    // 单选：传选项名字符串
81	    return String(value ?? '');
82	  }
83	  return value == null ? '' : String(value);
84	}
85	
86	/**
87	 * 拉取表字段并解析逻辑字段 → 真实字段名
88	 */
89	export async function resolveFieldMap(appToken, tableId, force = false) {
90	  if (
91	    !force &&
92	    fieldCache &&
93	    fieldCache.appToken === appToken &&
94	    fieldCache.tableId === tableId &&
95	    Date.now() - fieldCache.at < FIELD_CACHE_TTL
96	  ) {
97	    return fieldCache;
98	  }
99	
100	  const token = await getTenantAccessToken();
101	  const url = `${FEISHU.BITABLE_FIELDS(appToken, tableId)}?page_size=100`;
102	  const res = await fetch(url, {
103	    headers: { Authorization: `Bearer ${token}` }
104	  });
105	  const json = await res.json().catch(() => ({}));
106	  if (json.code !== 0) {
107	    throw new Error(
108	      `读取飞书表字段失败: code=${json.code} msg=${json.msg}。请确认 App Token / Table ID 正确，且应用已加入该多维表格。`
109	    );
110	  }
111	
112	  const items = json.data?.items || [];
113	  const names = items.map((f) => f.field_name).filter(Boolean);
114	  const byName = {};
115	  for (const f of items) {
116	    if (f.field_name) byName[f.field_name] = f;
117	  }
118	
119	  /** @type {Record<string, {name:string,type:number}>} */
120	  const map = {};
121	  for (const [key, aliases] of Object.entries(BITABLE_FIELD_ALIASES)) {
122	    for (const alias of aliases) {
