/**
 * Content Script（isolated world）
 * - 注入 fetch hook
 * - 响应 SCRAPE_PAGE：DOM + 缓存 API 数据
 *
 * 注意：不使用 ES module import，保证紫鸟/各 Chromium 版本兼容
 */

(() => {
  const HEADER_ALIASES = {
    campaign: [
      '品名',
      '广告系列',
      '广告系列名称',
      '系列名称',
      'campaign',
      'campaign name',
      'ad group',
      'product',
      '产品',
      '名称',
      'name'
    ],
    spend: [
      '广告花费',
      '广告成本',
      '花费',
      '成本',
      '消耗',
      'cost',
      'spend',
      'ad spend',
      'ad cost',
      'amount spent',
      'budget spent',
      'stat cost'
    ],
    orders: [
      '销量',
      '订单',
      '订单数',
      'sku 订单',
      'sku订单',
      'sku orders',
      'orders',
      'units',
      'units sold',
      'sold',
      'conversions',
      'purchases'
    ],
    roi: [
      'roi',
      'roas',
      '投资回报率',
      '投资回报',
      '回报率',
      'return on ad spend',
      'return on investment'
    ],
    revenue: [
      '销售额',
      '总收入',
      '销售收入',
      '收入',
      'gmv',
      'revenue',
      'gross revenue',
      'ads gross revenue',
      'gross merchandise',
      'sales'
    ]
  };

  const KEY_MAP = {
    campaign: [
      'campaign_name',
      'campaignName',
      'ad_name',
      'adName',
      'name',
      'title',
      'product_name',
      'productName'
    ],
    spend: [
      'spend',
      'cost',
      'ad_spend',
      'adSpend',
      'ad_cost',
      'stat_cost',
      'statCost',
      'amount_spent',
      'consume'
    ],
    orders: [
      'orders',
      'order_count',
      'orderCount',
      'sku_order_count',
      'skuOrderCount',
      'units',
      'units_sold',
      'unitsSold',
      'paid_order_count',
      'conversions'
    ],
    roi: ['roi', 'roas', 'ROI', 'ROAS', 'complete_payment_roas', 'net_roi'],
    revenue: [
      'revenue',
      'gmv',
      'gross_revenue',
      'grossRevenue',
      'total_revenue',
      'onsite_shopping_value',
      'sales',
      'income'
    ]
  };

  /** @type {{url:string, body:any, at:number}[]} */
  const apiCache = [];
  const API_CACHE_MAX = 30;

  // —— utils ——
  function cleanText(text) {
    return String(text ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function parseNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥USD|GBP|EUR]/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    // 排除「平均下单成本」等非广告花费列
    if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b|出价|budget(?!.*spent)/i.test(t)) {
      if (!/^(成本|花费|消耗|cost|spend|广告花费|广告成本)$/i.test(t)) {
        // 仍允许纯「成本/花费」通过；带「平均」的直接跳过 spend 匹配
      }
    }
    const order = ['roi', 'spend', 'orders', 'revenue', 'campaign'];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) {
          continue;
        }
        if (field === 'spend') {
          if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b/.test(t)) continue;
          if (
            t.includes('budget') &&
            !t.includes('spent') &&
            !t.includes('spend') &&
            !t.includes('cost') &&
            !t.includes('成本')
          ) {
            continue;
          }
        }
        // 「名称」太宽，要求更像广告系列
        if (field === 'campaign' && (al === '名称' || al === 'name')) {
          if (!/系列|campaign|广告|活动|product|品名/.test(t) && t !== '名称' && t !== 'name') {
            continue;
          }
        }
        // 「sales」勿抢销量列以外的无关列
        if (field === 'revenue' && al === 'sales' && /order|unit|sku|销量|订单/.test(t)) {
          continue;
        }
        return field;
      }
    }
    return null;
  }

  function extractTableHeaders(table) {
    let headerRow = table.querySelector('thead tr') || table.querySelector('tr');
    if (!headerRow) return { fields: [] };
    const cells = [...headerRow.querySelectorAll('th, td')];
    return {
      fields: cells.map((c) => matchHeaderField(c.innerText || c.textContent || ''))
    };
  }

