1	# Multi-store TikTok ad scrape via ziniao-cli (dynamic store list)
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun true
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun false
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -ListOnly
7	#
8	# Requires: Ziniao client running + ziniao-cli doctor OK
9	# Config: config\stores.config.json
10	
11	param(
12	  [string]$ConfigPath = "",
13	  [switch]$ListOnly,
14	  # string so -File callers work (Nullable[bool] cannot bind "$true"/"$false" from -File)
15	  # omit / empty => use config.options.dryRun; true|1|yes / false|0|no
16	  [string]$DryRun = ""
17	)
18	
19	$ErrorActionPreference = 'Stop'
20	# ziniao-cli writes progress to stderr; do not treat as terminating
21	$PSNativeCommandUseErrorActionPreference = $false
22	$root = Split-Path $PSScriptRoot -Parent
23	if (-not $ConfigPath) {
24	  $ConfigPath = Join-Path $root 'config\stores.config.json'
25	}
26	$scrapeJsPath = Join-Path $root 'scripts\scrape-ads-page.js'
27	
28	if (-not (Test-Path $ConfigPath)) {
29	  throw "Missing config: $ConfigPath (copy config\stores.config.example.json)"
30	}
31	if (-not (Test-Path $scrapeJsPath)) {
32	  throw "Missing scrape script: $scrapeJsPath"
33	}
34	
35	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
36	$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
37	$analysisLib = Join-Path $PSScriptRoot 'daily-analysis.ps1'
38	if (Test-Path $analysisLib) { . $analysisLib }
39	
40	function Write-Step([string]$msg) {
41	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
42	}
43	
44	function Get-BizDate([string]$mode) {
45	  $d = Get-Date
46	  if ($mode -eq 'yesterday') { $d = $d.AddDays(-1) }
47	  return $d.ToString('yyyy-MM-dd')
48	}
49	
50	function Test-StoreFilter($store, $filter) {
51	  if ($filter.includeStoreIds -and @($filter.includeStoreIds).Count -gt 0) {
52	    if ($store.storeId -notin @($filter.includeStoreIds)) { return $false }
53	  }
54	  if ($filter.excludeStoreIds -and ($store.storeId -in @($filter.excludeStoreIds))) {
55	    return $false
56	  }
57	  if ($filter.requireIp -eq $true) {
58	    if (-not $store.ip -or [string]::IsNullOrWhiteSpace([string]$store.ip)) { return $false }
59	  }
60	  $platform = [string]$store.platformName
61	  $name = [string]$store.storeName
62	  if ($filter.platformContains -and @($filter.platformContains).Count -gt 0) {
63	    $ok = $false
64	    foreach ($p in @($filter.platformContains)) {
65	      if ($platform -like "*$p*") { $ok = $true; break }
66	    }
67	    if (-not $ok) { return $false }
68	  }
69	  if ($filter.nameContains -and @($filter.nameContains).Count -gt 0) {
70	    $ok = $false
71	    foreach ($p in @($filter.nameContains)) {
72	      if ($name -like "*$p*") { $ok = $true; break }
73	    }
74	    if (-not $ok) { return $false }
75	  }
76	  if ($filter.nameExclude) {
77	    foreach ($p in @($filter.nameExclude)) {
78	      if ($name -like "*$p*") { return $false }
79	    }
80	  }
81	  return $true
82	}
83	
84	function Get-AdsUrl($store, $adsUrlCfg) {
85	  $platform = [string]$store.platformName
86	  if ($adsUrlCfg.byPlatform) {
87	    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
88	      if ($p.Name -eq $platform) { return [string]$p.Value }
89	    }
90	    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
91	      if ($platform -like "*$($p.Name)*") { return [string]$p.Value }
92	    }
93	  }
94	  return [string]$adsUrlCfg.default
95	}
96	
97	function Get-DisplayName($store, $map) {
98	  $name = [string]$store.storeName
99	  if ($map) {
100	    foreach ($p in $map.PSObject.Properties) {
101	      if ($p.Name -eq $name) { return [string]$p.Value }
102	    }
103	    foreach ($p in $map.PSObject.Properties) {
104	      if ($name -like "*$($p.Name)*" -or $p.Name -like "*$name*") {
105	        return [string]$p.Value
106	      }
107	    }
108	  }
109	  return $name
110	}
111	
112	function Get-FeishuToken($appId, $appSecret) {
113	  $body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
114	  $r = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' `
115	    -ContentType 'application/json; charset=utf-8' -Body $body
116	  if ($r.code -ne 0) { throw "Feishu token failed: $($r.msg)" }
117	  return $r.tenant_access_token
118	}
119	
120	function Write-FeishuRows($feishu, $rows, $dryRun) {
121	  if ($dryRun) {
122	    Write-Step ("  [dry-run] skip Feishu write, rows={0}" -f $rows.Count)
123	    return @{ written = 0; dryRun = $true }
124	  }
125	  if (-not $rows.Count) { return @{ written = 0; dryRun = $false } }
126	
127	  $token = Get-FeishuToken $feishu.appId $feishu.appSecret
128	  $url = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/records/batch_create"
129	  $fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/fields?page_size=100"
130	  $fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers @{ Authorization = "Bearer $token" }
131	  $names = @($fieldList.data.items | ForEach-Object { $_.field_name })
132	
133	  function Pick-Name([string[]]$aliases) {
134	    foreach ($a in $aliases) { if ($names -contains $a) { return $a } }
135	    return $null
136	  }
137	
138	  # UTF-8 field names (same as extension BITABLE_FIELDS)
139	  $utf8 = [System.Text.Encoding]::UTF8
140	  $A_DATE = @($utf8.GetString([byte[]](0xE6,0x97,0xA5,0xE6,0x9C,0x9F)))
141	  $A_STORE = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA)))
142	  $A_STORE_ID = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA,0x49,0x44)))
143	  $A_CAMPAIGN = @(
144	    $utf8.GetString([byte[]](0xE5,0x93,0x81,0xE5,0x90,0x8D)),
145	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE7,0xB3,0xBB,0xE5,0x88,0x97,0xE5,0x90,0x8D,0xE7,0xA7,0xB0))
146	  )
147	  $A_SPEND = @(
148	    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE8,0x8A,0xB1,0xE8,0xB4,0xB9)),
149	    $utf8.GetString([byte[]](0xE6,0x88,0x90,0xE6,0x9C,0xAC))
150	  )
151	  $A_ORDERS = @($utf8.GetString([byte[]](0xE9,0x94,0x80,0xE9,0x87,0x8F)))
152	  $A_ROI = @('ROI')
153	  $A_REVENUE = @(
154	    $utf8.GetString([byte[]](0xE9,0x94,0x80,0xE5,0x94,0xAE,0xE9,0xA2,0x9D)),
155	    $utf8.GetString([byte[]](0xE6,0x80,0xBB,0xE6,0x94,0xB6,0xE5,0x85,0xA5))
156	  )
157	  $A_SCRAPED = @($utf8.GetString([byte[]](0xE6,0x8A,0x93,0xE5,0x8F,0x96,0xE6,0x97,0xB6,0xE9,0x97,0xB4)))
158	  $A_URL = @($utf8.GetString([byte[]](0xE6,0x95,0xB0,0xE6,0x8D,0xAE,0xE6,0xBA,0x90,0x55,0x52,0x4C)))
159	  $A_STATUS = @($utf8.GetString([byte[]](0xE7,0x8A,0xB6,0xE6,0x80,0x81)))
160	
161	  $fn = @{
162	    date      = Pick-Name $A_DATE
163	    store     = Pick-Name $A_STORE
164	    storeId   = Pick-Name $A_STORE_ID
165	    campaign  = Pick-Name $A_CAMPAIGN
166	    spend     = Pick-Name $A_SPEND
167	    orders    = Pick-Name $A_ORDERS
168	    roi       = Pick-Name $A_ROI
169	    revenue   = Pick-Name $A_REVENUE
170	    scrapedAt = Pick-Name $A_SCRAPED
171	    sourceUrl = Pick-Name $A_URL
172	    status    = Pick-Name $A_STATUS
173	  }
174	
175	  if (-not $fn.campaign -or -not $fn.store) {
176	    throw ("Feishu fields incomplete. Have: {0}" -f ($names -join ', '))
177	  }
178	
179	  $records = @()
180	  foreach ($row in $rows) {
181	    $fields = @{}
182	    if ($fn.date) {
183	      $dt = [DateTime]::ParseExact($row.date, 'yyyy-MM-dd', $null)
184	      $fields[$fn.date] = [DateTimeOffset]::new($dt).ToUnixTimeMilliseconds()
185	    }
186	    if ($fn.store) { $fields[$fn.store] = $row.store }
187	    if ($fn.storeId) { $fields[$fn.storeId] = $row.storeId }
188	    if ($fn.campaign) { $fields[$fn.campaign] = $row.campaign }
189	    if ($fn.spend) { $fields[$fn.spend] = [double]$row.spend }
190	    if ($fn.orders) { $fields[$fn.orders] = [double]$row.orders }
191	    if ($fn.roi) { $fields[$fn.roi] = [double]$row.roi }
192	    if ($fn.revenue) { $fields[$fn.revenue] = [double]$row.revenue }
193	    if ($fn.scrapedAt) { $fields[$fn.scrapedAt] = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() }
194	    if ($fn.sourceUrl) { $fields[$fn.sourceUrl] = $row.sourceUrl }
195	    if ($fn.status) { $fields[$fn.status] = $row.status }
196	    $records += @{ fields = $fields }
197	  }
198	
199	  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes((@{ records = $records } | ConvertTo-Json -Depth 8 -Compress))
200	  $resp = Invoke-RestMethod -Method POST -Uri $url -Headers @{ Authorization = "Bearer $token" } `
201	    -ContentType 'application/json; charset=utf-8' -Body $bodyBytes
202	  if ($resp.code -ne 0) {
203	    throw ("Feishu write failed: code={0} msg={1}" -f $resp.code, $resp.msg)
204	  }
205	  return @{ written = $records.Count; dryRun = $false }
206	}
207	
208	# --- main ---
209	function ConvertTo-ProcessArgument([string]$arg) {
210	  # CommandLineToArgvW-style quoting for ProcessStartInfo.Arguments
211	  if ($null -eq $arg) { return '""' }
212	  if ($arg -notmatch '[\s"]') { return $arg }
213	  $bs = [char]0x5C
