# Multi-store TikTok ad scrape via ziniao-cli (dynamic store list)
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun true
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun false
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -ListOnly
#
# Requires: Ziniao client running + ziniao-cli doctor OK
# Config: config\stores.config.json

param(
  [string]$ConfigPath = "",
  [switch]$ListOnly,
  # string so -File callers work (Nullable[bool] cannot bind "$true"/"$false" from -File)
  # omit / empty => use config.options.dryRun; true|1|yes / false|0|no
  [string]$DryRun = ""
)

$ErrorActionPreference = 'Stop'
# ziniao-cli writes progress to stderr; do not treat as terminating
$PSNativeCommandUseErrorActionPreference = $false
$root = Split-Path $PSScriptRoot -Parent
if (-not $ConfigPath) {
  $ConfigPath = Join-Path $root 'config\stores.config.json'
}
$scrapeJsPath = Join-Path $root 'scripts\scrape-ads-page.js'

if (-not (Test-Path $ConfigPath)) {
  throw "Missing config: $ConfigPath (copy config\stores.config.example.json)"
}
if (-not (Test-Path $scrapeJsPath)) {
  throw "Missing scrape script: $scrapeJsPath"
}

$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
$analysisLib = Join-Path $PSScriptRoot 'daily-analysis.ps1'
if (Test-Path $analysisLib) { . $analysisLib }

function Write-Step([string]$msg) {
  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
}

function Get-BizDate([string]$mode) {
  $d = Get-Date
  if ($mode -eq 'yesterday') { $d = $d.AddDays(-1) }
  return $d.ToString('yyyy-MM-dd')
}

function Test-StoreFilter($store, $filter) {
  if ($filter.includeStoreIds -and @($filter.includeStoreIds).Count -gt 0) {
    if ($store.storeId -notin @($filter.includeStoreIds)) { return $false }
  }
  if ($filter.excludeStoreIds -and ($store.storeId -in @($filter.excludeStoreIds))) {
    return $false
  }
  if ($filter.requireIp -eq $true) {
    if (-not $store.ip -or [string]::IsNullOrWhiteSpace([string]$store.ip)) { return $false }
  }
  $platform = [string]$store.platformName
  $name = [string]$store.storeName
  if ($filter.platformContains -and @($filter.platformContains).Count -gt 0) {
    $ok = $false
    foreach ($p in @($filter.platformContains)) {
      if ($platform -like "*$p*") { $ok = $true; break }
    }
    if (-not $ok) { return $false }
  }
  if ($filter.nameContains -and @($filter.nameContains).Count -gt 0) {
    $ok = $false
    foreach ($p in @($filter.nameContains)) {
      if ($name -like "*$p*") { $ok = $true; break }
    }
    if (-not $ok) { return $false }
  }
  if ($filter.nameExclude) {
    foreach ($p in @($filter.nameExclude)) {
      if ($name -like "*$p*") { return $false }
    }
  }
  return $true
}

function Get-AdsUrl($store, $adsUrlCfg) {
  $platform = [string]$store.platformName
  if ($adsUrlCfg.byPlatform) {
    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
      if ($p.Name -eq $platform) { return [string]$p.Value }
    }
    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
      if ($platform -like "*$($p.Name)*") { return [string]$p.Value }
    }
  }
  return [string]$adsUrlCfg.default
}

function Get-DisplayName($store, $map) {
  $name = [string]$store.storeName
  if ($map) {
    foreach ($p in $map.PSObject.Properties) {
      if ($p.Name -eq $name) { return [string]$p.Value }
    }
    foreach ($p in $map.PSObject.Properties) {
      if ($name -like "*$($p.Name)*" -or $p.Name -like "*$name*") {
        return [string]$p.Value
      }
    }
  }
  return $name
}

function Get-FeishuToken($appId, $appSecret) {
  $body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
  $r = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' `
    -ContentType 'application/json; charset=utf-8' -Body $body
  if ($r.code -ne 0) { throw "Feishu token failed: $($r.msg)" }
  return $r.tenant_access_token
}

function Write-FeishuRows($feishu, $rows, $dryRun) {
  if ($dryRun) {
    Write-Step ("  [dry-run] skip Feishu write, rows={0}" -f $rows.Count)
    return @{ written = 0; dryRun = $true }
  }
  if (-not $rows.Count) { return @{ written = 0; dryRun = $false } }

  $token = Get-FeishuToken $feishu.appId $feishu.appSecret
  $url = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/records/batch_create"
  $fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/fields?page_size=100"
  $fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers @{ Authorization = "Bearer $token" }
  $names = @($fieldList.data.items | ForEach-Object { $_.field_name })

  function Pick-Name([string[]]$aliases) {
    foreach ($a in $aliases) { if ($names -contains $a) { return $a } }
    return $null
  }

  # UTF-8 field names (same as extension BITABLE_FIELDS)
  $utf8 = [System.Text.Encoding]::UTF8
  $A_DATE = @($utf8.GetString([byte[]](0xE6,0x97,0xA5,0xE6,0x9C,0x9F)))
  $A_STORE = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA)))
  $A_STORE_ID = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA,0x49,0x44)))
  $A_CAMPAIGN = @(
    $utf8.GetString([byte[]](0xE5,0x93,0x81,0xE5,0x90,0x8D)),
    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE7,0xB3,0xBB,0xE5,0x88,0x97,0xE5,0x90,0x8D,0xE7,0xA7,0xB0))
  )
  $A_SPEND = @(
    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE8,0x8A,0xB1,0xE8,0xB4,0xB9)),
    $utf8.GetString([byte[]](0xE6,0x88,0x90,0xE6,0x9C,0xAC))
  )
  $A_ORDERS = @($utf8.GetString([byte[]](0xE9,0x94,0x80,0xE9,0x87,0x8F)))
  $A_ROI = @('ROI')
  $A_REVENUE = @(
    $utf8.GetString([byte[]](0xE9,0x94,0x80,0xE5,0x94,0xAE,0xE9,0xA2,0x9D)),
    $utf8.GetString([byte[]](0xE6,0x80,0xBB,0xE6,0x94,0xB6,0xE5,0x85,0xA5))
  )
  $A_SCRAPED = @($utf8.GetString([byte[]](0xE6,0x8A,0x93,0xE5,0x8F,0x96,0xE6,0x97,0xB6,0xE9,0x97,0xB4)))
  $A_URL = @($utf8.GetString([byte[]](0xE6,0x95,0xB0,0xE6,0x8D,0xAE,0xE6,0xBA,0x90,0x55,0x52,0x4C)))
  $A_STATUS = @($utf8.GetString([byte[]](0xE7,0x8A,0xB6,0xE6,0x80,0x81)))

  $fn = @{
    date      = Pick-Name $A_DATE
    store     = Pick-Name $A_STORE
    storeId   = Pick-Name $A_STORE_ID
    campaign  = Pick-Name $A_CAMPAIGN
    spend     = Pick-Name $A_SPEND
    orders    = Pick-Name $A_ORDERS
    roi       = Pick-Name $A_ROI
    revenue   = Pick-Name $A_REVENUE
    scrapedAt = Pick-Name $A_SCRAPED
    sourceUrl = Pick-Name $A_URL
    status    = Pick-Name $A_STATUS
  }

  if (-not $fn.campaign -or -not $fn.store) {
    throw ("Feishu fields incomplete. Have: {0}" -f ($names -join ', '))
  }

  $records = @()
  foreach ($row in $rows) {
    $fields = @{}
    if ($fn.date) {
      $dt = [DateTime]::ParseExact($row.date, 'yyyy-MM-dd', $null)
      $fields[$fn.date] = [DateTimeOffset]::new($dt).ToUnixTimeMilliseconds()
    }
    if ($fn.store) { $fields[$fn.store] = $row.store }
    if ($fn.storeId) { $fields[$fn.storeId] = $row.storeId }
    if ($fn.campaign) { $fields[$fn.campaign] = $row.campaign }
    if ($fn.spend) { $fields[$fn.spend] = [double]$row.spend }
    if ($fn.orders) { $fields[$fn.orders] = [double]$row.orders }
    if ($fn.roi) { $fields[$fn.roi] = [double]$row.roi }
    if ($fn.revenue) { $fields[$fn.revenue] = [double]$row.revenue }
    if ($fn.scrapedAt) { $fields[$fn.scrapedAt] = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() }
    if ($fn.sourceUrl) { $fields[$fn.sourceUrl] = $row.sourceUrl }
    if ($fn.status) { $fields[$fn.status] = $row.status }
    $records += @{ fields = $fields }
  }

  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes((@{ records = $records } | ConvertTo-Json -Depth 8 -Compress))
  $resp = Invoke-RestMethod -Method POST -Uri $url -Headers @{ Authorization = "Bearer $token" } `
    -ContentType 'application/json; charset=utf-8' -Body $bodyBytes
  if ($resp.code -ne 0) {
    throw ("Feishu write failed: code={0} msg={1}" -f $resp.code, $resp.msg)
  }
  return @{ written = $records.Count; dryRun = $false }
}

# --- main ---
function ConvertTo-ProcessArgument([string]$arg) {
  # CommandLineToArgvW-style quoting for ProcessStartInfo.Arguments
  if ($null -eq $arg) { return '""' }
  if ($arg -notmatch '[\s"]') { return $arg }
  $bs = [char]0x5C
  $sb = New-Object System.Text.StringBuilder
  [void]$sb.Append([char]0x22)
  $backslashes = 0
  foreach ($ch in $arg.ToCharArray()) {
    if ($ch -eq $bs) {
      $backslashes++
      continue
    }
    if ($ch -eq [char]0x22) {
      [void]$sb.Append($bs, $backslashes * 2 + 1)
      [void]$sb.Append([char]0x22)
      $backslashes = 0
      continue
    }
    if ($backslashes -gt 0) {
      [void]$sb.Append($bs, $backslashes)
      $backslashes = 0
    }
    [void]$sb.Append($ch)
  }
  if ($backslashes -gt 0) { [void]$sb.Append($bs, $backslashes * 2) }
  [void]$sb.Append([char]0x22)
  return $sb.ToString()
}

# Cache: npm ziniao-cli is a .ps1 shim — Process.Start cannot run it; invoke node + run.js directly
$script:ZiniaoNode = $null
$script:ZiniaoRunJs = $null

function Initialize-ZiniaoCli {
  if ($script:ZiniaoNode -and $script:ZiniaoRunJs) { return }

  $nodeCmd = Get-Command node -ErrorAction SilentlyContinue
  if (-not $nodeCmd) { throw "node not found in PATH (required by ziniao-cli)" }
  $script:ZiniaoNode = $nodeCmd.Source

  $candidates = @()

# Daily report summary + analysis helpers (dot-source from run-multi-store.ps1)
# Produces: store rollups, overall KPI, highlights, risks, markdown report

function ConvertTo-DoubleSafe($v) {
  if ($null -eq $v -or $v -eq '') { return 0.0 }
  try { return [double]$v } catch { return 0.0 }
}

function Get-BlendedRoi([double]$spend, [double]$revenue) {
  if ($spend -le 0) {
    if ($revenue -gt 0) { return 999.0 }
    return 0.0
  }
  return [Math]::Round($revenue / $spend, 2)
}

function Build-DailyAnalysis {
  param(
    [object[]]$CampaignRows,
    [object[]]$RunSummary,
    [string]$BizDate,
    [double]$LowRoiThreshold = 3.0,
    [int]$TopN = 5
  )

  $rows = @($CampaignRows | Where-Object { $_ -and $_.campaign -and ($_.campaign -notmatch '汇总|分析|合计') })
  $byStore = @{}
  foreach ($r in $rows) {
    $key = [string]$r.store
    if (-not $byStore.ContainsKey($key)) {
      $byStore[$key] = [ordered]@{
        store       = $key
        storeId     = [string]$r.storeId
        campaigns   = 0
        spend       = 0.0
        orders      = 0.0
        revenue     = 0.0
        topCampaign = $null
        topRevenue  = -1.0
        lowRoiCount = 0
        zeroRevSpend = 0
      }
    }
    $s = $byStore[$key]
    $spend = ConvertTo-DoubleSafe $r.spend
    $orders = ConvertTo-DoubleSafe $r.orders
    $revenue = ConvertTo-DoubleSafe $r.revenue
    $roi = ConvertTo-DoubleSafe $r.roi
    $s.campaigns++
    $s.spend += $spend
    $s.orders += $orders
    $s.revenue += $revenue
    if ($revenue -gt $s.topRevenue) {
      $s.topRevenue = $revenue
      $s.topCampaign = [string]$r.campaign
    }
    if ($spend -gt 0 -and $roi -gt 0 -and $roi -lt $LowRoiThreshold) { $s.lowRoiCount++ }
    if ($spend -gt 0 -and $revenue -le 0) { $s.zeroRevSpend++ }
    $byStore[$key] = $s
  }

  $storeRollups = @()
  foreach ($k in ($byStore.Keys | Sort-Object)) {
    $s = $byStore[$k]
    $s.spend = [Math]::Round([double]$s.spend, 2)
    $s.orders = [Math]::Round([double]$s.orders, 0)
    $s.revenue = [Math]::Round([double]$s.revenue, 2)
    $s.roi = Get-BlendedRoi $s.spend $s.revenue
    $storeRollups += [pscustomobject]$s
  }

  $totalSpend = [Math]::Round(($storeRollups | Measure-Object -Property spend -Sum).Sum, 2)
  if (-not $totalSpend) { $totalSpend = 0 }
  $totalOrders = [Math]::Round(($storeRollups | Measure-Object -Property orders -Sum).Sum, 0)
  if (-not $totalOrders) { $totalOrders = 0 }
  $totalRevenue = [Math]::Round(($storeRollups | Measure-Object -Property revenue -Sum).Sum, 2)
  if (-not $totalRevenue) { $totalRevenue = 0 }
  $totalCampaigns = ($storeRollups | Measure-Object -Property campaigns -Sum).Sum
  if (-not $totalCampaigns) { $totalCampaigns = 0 }
  $overallRoi = Get-BlendedRoi $totalSpend $totalRevenue

  $okStores = @($RunSummary | Where-Object { $_.ok }).Count
  $failStores = @($RunSummary | Where-Object { -not $_.ok })

  $topByRevenue = @($rows | Sort-Object { ConvertTo-DoubleSafe $_.revenue } -Descending | Select-Object -First $TopN)
  $topByRoi = @(
    $rows |
      Where-Object { (ConvertTo-DoubleSafe $_.spend) -gt 0 -and (ConvertTo-DoubleSafe $_.roi) -gt 0 } |
      Sort-Object { ConvertTo-DoubleSafe $_.roi } -Descending |
      Select-Object -First $TopN
  )
  $riskRows = @(
    $rows | Where-Object {
      $sp = ConvertTo-DoubleSafe $_.spend
      $rv = ConvertTo-DoubleSafe $_.revenue
      $ro = ConvertTo-DoubleSafe $_.roi
      ($sp -gt 0 -and $rv -le 0) -or ($sp -gt 0 -and $ro -gt 0 -and $ro -lt $LowRoiThreshold)
    } | Select-Object -First 20
  )

  $highlights = New-Object System.Collections.Generic.List[string]
  $risks = New-Object System.Collections.Generic.List[string]

  if ($storeRollups.Count -gt 0) {
    $bestStore = $storeRollups | Sort-Object revenue -Descending | Select-Object -First 1
    $highlights.Add(("销售额最高店铺：{0}（销售额 {1}，花费 {2}，综合 ROI {3}）" -f $bestStore.store, $bestStore.revenue, $bestStore.spend, $bestStore.roi))
    $eff = @($storeRollups | Where-Object { $_.spend -gt 0 }) | Sort-Object roi -Descending | Select-Object -First 1
    if ($eff) {
      $highlights.Add(("综合 ROI 最高店铺：{0}（ROI {1}，花费 {2}）" -f $eff.store, $eff.roi, $eff.spend))
    }
  }
  if ($topByRevenue.Count -gt 0) {
    $t = $topByRevenue[0]
    $highlights.Add(("单系列销售额 TOP1：[{0}] {1}（销售额 {2}，ROI {3}）" -f $t.store, $t.campaign, (ConvertTo-DoubleSafe $t.revenue), (ConvertTo-DoubleSafe $t.roi)))
  }

  foreach ($s in $storeRollups) {
    if ($s.spend -gt 0 -and $s.roi -gt 0 -and $s.roi -lt $LowRoiThreshold) {
      $risks.Add(("店铺 {0} 综合 ROI {1} 低于阈值 {2}，建议复核出价/素材/选品" -f $s.store, $s.roi, $LowRoiThreshold))
    }
    if ($s.zeroRevSpend -gt 0) {
      $risks.Add(("店铺 {0} 有 {1} 个系列花费>0 但销售额为 0" -f $s.store, $s.zeroRevSpend))
    }
  }
  foreach ($f in $failStores) {
    $risks.Add(("抓取失败：{0} — {1}" -f $f.displayName, $f.error))
  }
  if ($risks.Count -eq 0) {
    $risks.Add("未发现明显异常（按当前阈值）。")
  }

  $md = New-Object System.Text.StringBuilder
  [void]$md.AppendLine("# TK 广告日报分析")
  [void]$md.AppendLine("")
  [void]$md.AppendLine(("> 业务日期：**{0}** · 生成时间：{1}" -f $BizDate, (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')))
  [void]$md.AppendLine("")
  [void]$md.AppendLine("## 1. 总览")
  [void]$md.AppendLine("")
  [void]$md.AppendLine(("| 指标 | 数值 |"))
  [void]$md.AppendLine(("| --- | --- |"))
  [void]$md.AppendLine(("| 成功/计划店铺 | {0} / {1} |" -f $okStores, @($RunSummary).Count))
  [void]$md.AppendLine(("| 广告系列数 | {0} |" -f $totalCampaigns))
  [void]$md.AppendLine(("| 广告花费合计 | {0} |" -f $totalSpend))
  [void]$md.AppendLine(("| 销量合计 | {0} |" -f $totalOrders))
  [void]$md.AppendLine(("| 销售额合计 | {0} |" -f $totalRevenue))
  [void]$md.AppendLine(("| 综合 ROI | {0} |" -f $overallRoi))
  [void]$md.AppendLine("")
  [void]$md.AppendLine("## 2. 分店铺汇总")
  [void]$md.AppendLine("")
  [void]$md.AppendLine("| 店铺 | 系列数 | 广告花费 | 销量 | 销售额 | 综合ROI | 贡献TOP系列 |")
  [void]$md.AppendLine("| --- | ---: | ---: | ---: | ---: | ---: | --- |")
  foreach ($s in ($storeRollups | Sort-Object revenue -Descending)) {
    [void]$md.AppendLine(("| {0} | {1} | {2} | {3} | {4} | {5} | {6} |" -f `
      $s.store, $s.campaigns, $s.spend, $s.orders, $s.revenue, $s.roi, $s.topCampaign))
  }
  [void]$md.AppendLine("")
  [void]$md.AppendLine("## 3. 亮点")
  [void]$md.AppendLine("")
  foreach ($h in $highlights) { [void]$md.AppendLine(("- {0}" -f $h)) }
  [void]$md.AppendLine("")
  [void]$md.AppendLine(("## 4. 风险与建议（ROI 阈值 < {0}）" -f $LowRoiThreshold))
  [void]$md.AppendLine("")
  foreach ($r in $risks) { [void]$md.AppendLine(("- {0}" -f $r)) }
  [void]$md.AppendLine("")
  [void]$md.AppendLine("## 5. 系列 TOP（按销售额）")
  [void]$md.AppendLine("")
  [void]$md.AppendLine("| 店铺 | 品名 | 花费 | 销量 | ROI | 销售额 |")
  [void]$md.AppendLine("| --- | --- | ---: | ---: | ---: | ---: |")
  foreach ($t in $topByRevenue) {
    [void]$md.AppendLine(("| {0} | {1} | {2} | {3} | {4} | {5} |" -f `
      $t.store, $t.campaign, (ConvertTo-DoubleSafe $t.spend), (ConvertTo-DoubleSafe $t.orders), (ConvertTo-DoubleSafe $t.roi), (ConvertTo-DoubleSafe $t.revenue)))
  }
  [void]$md.AppendLine("")
  [void]$md.AppendLine("## 6. 系列 TOP（按 ROI，花费>0）")
  [void]$md.AppendLine("")
  [void]$md.AppendLine("| 店铺 | 品名 | 花费 | 销量 | ROI | 销售额 |")
  [void]$md.AppendLine("| --- | --- | ---: | ---: | ---: | ---: |")
  foreach ($t in $topByRoi) {
    [void]$md.AppendLine(("| {0} | {1} | {2} | {3} | {4} | {5} |" -f `
      $t.store, $t.campaign, (ConvertTo-DoubleSafe $t.spend), (ConvertTo-DoubleSafe $t.orders), (ConvertTo-DoubleSafe $t.roi), (ConvertTo-DoubleSafe $t.revenue)))
  }
  if ($riskRows.Count -gt 0) {
    [void]$md.AppendLine("")
    [void]$md.AppendLine("## 7. 需关注系列（摘录）")
    [void]$md.AppendLine("")
    foreach ($t in $riskRows) {
      [void]$md.AppendLine(("- [{0}] {1} · 花费 {2} · ROI {3} · 销售额 {4}" -f `
        $t.store, $t.campaign, (ConvertTo-DoubleSafe $t.spend), (ConvertTo-DoubleSafe $t.roi), (ConvertTo-DoubleSafe $t.revenue)))
    }
  }

  $brief = New-Object System.Text.StringBuilder
  [void]$brief.AppendLine(("【TK广告日报 {0}】" -f $BizDate))
  [void]$brief.AppendLine(("总览：店铺 {0}/{1} 成功 · 系列 {2} · 花费 {3} · 销量 {4} · 销售额 {5} · 综合ROI {6}" -f `
    $okStores, @($RunSummary).Count, $totalCampaigns, $totalSpend, $totalOrders, $totalRevenue, $overallRoi))
  foreach ($h in $highlights) { [void]$brief.AppendLine(("亮点：{0}" -f $h)) }
  $riskHead = @($risks | Select-Object -First 5)
  foreach ($r in $riskHead) { [void]$brief.AppendLine(("关注：{0}" -f $r)) }

  return [pscustomobject]@{

