272	function Invoke-Ziniao([string[]]$CliArgs) {
273	  # UTF-8 capture via ProcessStartInfo. npm ziniao-cli is .ps1 — call node run.js instead.
274	  Initialize-ZiniaoCli
275	  $utf8 = [System.Text.UTF8Encoding]::new($false)
276	
277	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
278	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
279	
280	  $psi = New-Object System.Diagnostics.ProcessStartInfo
281	  $psi.FileName = $script:ZiniaoNode
282	  $psi.Arguments = $argLine
283	  $psi.UseShellExecute = $false
284	  $psi.RedirectStandardOutput = $true
285	  $psi.RedirectStandardError = $true
286	  $psi.CreateNoWindow = $true
287	  $psi.StandardOutputEncoding = $utf8
288	  $psi.StandardErrorEncoding = $utf8
289	
290	  $p = New-Object System.Diagnostics.Process
291	  $p.StartInfo = $psi
292	  try {
293	    [void]$p.Start()
294	  } catch {
295	    throw "Failed to start ziniao (node): $($_.Exception.Message)"
296	  }
297	  $stdout = $p.StandardOutput.ReadToEnd()
298	  $stderr = $p.StandardError.ReadToEnd()
299	  $p.WaitForExit()
300	
301	  $parts = @()
302	  if (-not [string]::IsNullOrEmpty($stdout)) { $parts += $stdout.TrimEnd("`r", "`n") }
303	  if (-not [string]::IsNullOrEmpty($stderr)) { $parts += $stderr.TrimEnd("`r", "`n") }
304	  return ($parts -join "`n")
305	}
