348	function ConvertTo-ScrapeOneLine([string]$js) {
349	  # // comments become catastrophic when newlines are removed — strip first
350	  $s = [regex]::Replace($js, '/\*[\s\S]*?\*/', ' ')
351	  $s = [regex]::Replace($s, '(?m)^\s*//.*$', '')
352	  $s = [regex]::Replace($s, '(?m)([^:"''\\])//[^\r\n]*', '$1')
353	  $s = ($s -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
354	  if ($s -notmatch '\)\s*\(\s*\)\s*;?\s*$' -and $s -notmatch '\}\s*\)\s*\(\s*\)\s*;?\s*$') {
355	    Write-Step "WARN scrape script may be truncated (len=$($s.Length))"
356	  }
357	  return $s
358	}
359	
360	function ConvertFrom-JsonSafe([string]$text) {
361	  if ([string]::IsNullOrWhiteSpace($text)) { return $null }
362	  try { return ($text | ConvertFrom-Json) } catch { return $null }
363	}
364	
365	function Get-ScrapePayload([string]$execOut) {
366	  # ziniao-cli page exec shapes seen in the wild:
367	  #   { ok, data: { ok, storeId, data: { exceptionDetails, result: "<json string>", targetId } } }
368	  #   { ok, data: { data: { result: { type, value: "<json string>" } } } }  (raw CDP)
369	  # Our scraper returns JSON.stringify({ ok, rows, source, url, error })
370	  function Test-ScrapeShape($o) {
371	    if ($null -eq $o) { return $false }
372	    if ($o -is [string]) { return $false }
373	    $names = @($o.PSObject.Properties.Name)
374	    return ($names -contains 'rows') -or (($names -contains 'ok') -and ($names -contains 'source' -or $names -contains 'error'))
375	  }
376	  function Convert-MaybeJsonString($v) {
377	    if ($v -is [string]) {
378	      $inner = ConvertFrom-JsonSafe $v
379	      if (Test-ScrapeShape $inner) { return $inner }
380	      return $null
381	    }
382	    if (Test-ScrapeShape $v) { return $v }
383	    if ($v -and ($v.PSObject.Properties.Name -contains 'value')) {
384	      return Convert-MaybeJsonString $v.value
385	    }
386	    return $null
387	  }
388	
389	  $root = ConvertFrom-JsonSafe $execOut
390	  if (-not $root) {
391	    if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
392	      return (ConvertFrom-JsonSafe $Matches[1])
393	    }
394	    return $null
395	  }
396	
397	  # Walk common nest paths first
398	  $paths = @(
399	    { param($r) $r },
400	    { param($r) $r.data },
401	    { param($r) $r.data.data },
402	    { param($r) $r.data.result },
403	    { param($r) $r.data.data.result },
404	    { param($r) $r.data.data.result.value },
405	    { param($r) $r.result },
406	    { param($r) $r.result.value }
407	  )
408	  foreach ($get in $paths) {
409	    try {
410	      $node = & $get $root
411	    } catch { continue }
412	    if ($null -eq $node) { continue }
413	
414	    # exception on this node?
415	    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'exceptionDetails' -and $node.exceptionDetails) {
416	      $ex = $node.exceptionDetails
417	      $msg = if ($ex.exception -and $ex.exception.description) { [string]$ex.exception.description }
418	             elseif ($ex.text) { [string]$ex.text }
419	             else { 'page exec exception' }
420	      return [pscustomobject]@{ ok = $false; rows = @(); error = $msg; source = 'exception' }
421	    }
422	
423	    $parsed = Convert-MaybeJsonString $node
424	    if ($parsed) { return $parsed }
425	
426	    # node has .result string/object
427	    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'result') {
428	      $parsed = Convert-MaybeJsonString $node.result
429	      if ($parsed) { return $parsed }
430	    }
431	  }
432	
433	  # Fallback: unescaped scrape JSON embedded in the CLI text
434	  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"\s*:[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
435	    $inner = ConvertFrom-JsonSafe $Matches[1]
436	    if ($inner) { return $inner }
437	  }
438	  # Escaped form inside result:"{...}"
439	  if ($execOut -match '"result"\s*:\s*"(\{\\"ok\\".+?\})"') {
440	    $unescaped = $Matches[1] -replace '\\"', '"' -replace '\\\\', '\'
441	    $inner = ConvertFrom-JsonSafe $unescaped
442	    if ($inner) { return $inner }
443	  }
444	
445	  return [pscustomobject]@{
446	    ok         = $false
447	    rows       = @()
448	    error      = 'unrecognized page exec payload'
449	    source     = 'parse'
450	    rawPreview = if ($execOut.Length -gt 400) { $execOut.Substring(0, 400) } else { $execOut }
451	  }
452	}
