1	/**
2	 * 注入到页面主世界：hook fetch / XHR，把疑似报表响应 post 给 content script
3	 * 注意：此文件不能用 ES module
4	 */
5	(function () {
6	  if (window.__TK_AD_FETCH_HOOKED__) return;
7	  window.__TK_AD_FETCH_HOOKED__ = true;
8	
9	  const REPORT_RE =
10	    /report|stat|metric|campaign|gmv|ads?\/api|shop_ads|analytics|performance|overview|data_list|getlist|insight/i;
11	
12	  function isLikely(url) {
13	    try {
14	      return REPORT_RE.test(String(url || ''));
15	    } catch {
16	      return false;
17	    }
18	  }
19	
20	  function emit(url, body) {
21	    try {
22	      window.postMessage(
23	        {
24	          source: 'tk-ad-scraper-hook',
25	          type: 'API_PAYLOAD',
26	          url: String(url || ''),
27	          body
28	        },
29	        '*'
30	      );
31	    } catch (_) {
32	      /* ignore */
33	    }
34	  }
35	
36	  const rawFetch = window.fetch;
37	  if (typeof rawFetch === 'function') {
38	    window.fetch = async function (...args) {
39	      const res = await rawFetch.apply(this, args);
40	      try {
41	        const url = typeof args[0] === 'string' ? args[0] : args[0]?.url || '';
42	        if (isLikely(url)) {
43	          const clone = res.clone();
44	          clone
45	            .text()
46	            .then((text) => {
47	              let body = text;
48	              try {
49	                body = JSON.parse(text);
50	              } catch (_) {
51	                /* keep text */
52	              }
53	              emit(url, body);
54	            })
55	            .catch(() => {});
56	        }
57	      } catch (_) {
58	        /* ignore */
59	      }
60	      return res;
61	    };
62	  }
63	
64	  const XO = XMLHttpRequest.prototype.open;
65	  const XS = XMLHttpRequest.prototype.send;
66	  XMLHttpRequest.prototype.open = function (method, url, ...rest) {
67	    this.__tkAdUrl = url;
68	    return XO.call(this, method, url, ...rest);
69	  };
70	  XMLHttpRequest.prototype.send = function (...args) {
71	    this.addEventListener('load', function () {
72	      try {
73	        if (!isLikely(this.__tkAdUrl)) return;
74	        let body = this.responseText;
75	        try {
76	          body = JSON.parse(this.responseText);
77	        } catch (_) {
78	          /* keep */
79	        }
80	        emit(this.__tkAdUrl, body);
81	      } catch (_) {
82	        /* ignore */
83	      }
84	    });
85	    return XS.apply(this, args);
86	  };
87	})();
